    trailing blanks. *)
Lemma gbo_0RB0LB_0RC1LA_1LB1RD_1LA1RC : forall j, lift (cden [] [] j BB1_0RB0LB_0RC1LA_1LB1RD_1LA1RC) = lift (Cin (pow2 j)).
