  - exists (4 * j + 8), (cden [] [] j BB1_0RB0LB_0RC1LA_1LB1RD_1LA1RC).
    split; [lia|]. split; [| exact (gbo_0RB0LB_0RC1LA_1LB1RD_1LA1RC j)].
    rewrite (gso_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j E).
    exact (srun_sound tm true true chb_0RB0LB_0RC1LA_1LB1RD_1LA1RC B0_0RB0LB_0RC1LA_1LB1RD_1LA1RC BB1_0RB0LB_0RC1LA_1LB1RD_1LA1RC 4 8
             run_boot_0RB0LB_0RC1LA_1LB1RD_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_0RB0LB_0RC1LA_1LB1RD_1LA1RC).
    split; [| exact (geo_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j E)].
    rewrite (gxi_0RB0LB_0RC1LA_1LB1RD_1LA1RC j).
    exact (srun_sound tm true true che_0RB0LB_0RC1LA_1LB1RD_1LA1RC BE0_0RB0LB_0RC1LA_1LB1RD_1LA1RC B1_0RB0LB_0RC1LA_1LB1RD_1LA1RC 4 10
             run_exit_0RB0LB_0RC1LA_1LB1RD_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LB_0RC1LA_1LB1RD_1LA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j' E).
Qed.

