(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LB_0RC1LA_1LB1RD_1LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LB_0RC1LA_1LB1RD_1LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LB_0RC1LA_1LB1RD_1LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LB_0RC1LA_1LB1RD_1LA1RC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB0LB_0RC1LA_1LB1RD_1LA1RC). split;
      [| exact (gbo_0RB0LB_0RC1LA_1LB1RD_1LA1RC j)].
    rewrite (gso_0RB0LB_0RC1LA_1LB1RD_1LA1RC p j E).
    exact (srun_sound tm true true chb_0RB0LB_0RC1LA_1LB1RD_1LA1RC B0_0RB0LB_0RC1LA_1LB1RD_1LA1RC BB1_0RB0LB_0RC1LA_1LB1RD_1LA1RC 4 8
             run_boot_0RB0LB_0RC1LA_1LB1RD_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LB_0RC1LA_1LB1RD_1LA1RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LB_0RC1LA_1LB1RD_1LA1RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LB_0RC1LA_1LB1RD_1LA1RC : forall t, ~ In t pins_0RB0LB_0RC1LA_1LB1RD_1LA1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0LB_0RC1LA_1LB1RD_1LA1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC [SWinR 2; SCycL 2 0; SWin 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC [SWinR 2; SCycL 2 0; SWin 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LB_0RC1LA_1LB1RD_1LA1RC [SWinR 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
