  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LB_1LC1RD_0RD0LC_1RB1LA (StD, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LB_1LC1RD_0RD0LC_1RB1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

