(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB0LC_0LC0LC_0RD1LA_1LC1RD : forall j, lift (cden [] [] j BB1_0RB0LC_0LC0LC_0RD1LA_1LC1RD) = lift (Cin (pow2 j)).
