    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_0LC0LC_0RD1LA_1LC1RD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_0LC0LC_0RD1LA_1LC1RD.
