  unfold Cin_0RB0LC_0LC0LC_0RD1LA_1LC1RD, cden, BE0_0RB0LC_0LC0LC_0RD1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
