  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_0LC0LC_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_0LC0LC_0RD1LA_1LC1RD p (pow2 j)).
  - exists (4 * j + 11), (cden [] [] j BB1_0RB0LC_0LC0LC_0RD1LA_1LC1RD).
    split; [lia|]. split; [| exact (gbo_0RB0LC_0LC0LC_0RD1LA_1LC1RD j)].
    rewrite (gso_0RB0LC_0LC0LC_0RD1LA_1LC1RD p j E).
    exact (srun_sound tm true true chb_0RB0LC_0LC0LC_0RD1LA_1LC1RD B0_0RB0LC_0LC0LC_0RD1LA_1LC1RD BB1_0RB0LC_0LC0LC_0RD1LA_1LC1RD 4 11
             run_boot_0RB0LC_0LC0LC_0RD1LA_1LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_0RB0LC_0LC0LC_0RD1LA_1LC1RD).
    split; [| exact (geo_0RB0LC_0LC0LC_0RD1LA_1LC1RD p j E)].
    rewrite (gxi_0RB0LC_0LC0LC_0RD1LA_1LC1RD j).
    exact (srun_sound tm true true che_0RB0LC_0LC0LC_0RD1LA_1LC1RD BE0_0RB0LC_0LC0LC_0RD1LA_1LC1RD B1_0RB0LC_0LC0LC_0RD1LA_1LC1RD 4 9
             run_exit_0RB0LC_0LC0LC_0RD1LA_1LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_0LC0LC_0RD1LA_1LC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
