(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_0RC1LD_0RD1LA_1LC1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB0LC_0RC1LD_0RD1LA_1LC1RD.
