(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LC_0RC1LD_0RD1LA_1LC1RD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB0LC_0RC1LD_0RD1LA_1LC1RD) = lift (Cc (Pos.succ p)).
Proof.
