Lemma geo_0RB0LC_0RC1LD_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_0RC1LD_0RD1LA_1LC1RD) = lift (Cc (Pos.succ p)).
