(** ** The lap *)

Lemma lap_0RB0LC_0RC1LD_0RD1LA_1LC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
