  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_0RC1LD_0RD1LA_1LC1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_0RC1LD_0RD1LA_1LC1RD B0_0RB0LC_0RC1LD_0RD1LA_1LC1RD B1_0RB0LC_0RC1LD_0RD1LA_1LC1RD 4 11 p j' [] []).
    + exact run_ovf_0RB0LC_0RC1LD_0RD1LA_1LC1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_0RC1LD_0RD1LA_1LC1RD p j' E).
    + exact (geo_0RB0LC_0RC1LD_0RD1LA_1LC1RD p j' E).
    + lia.
