    split; [lia|]. split; [| exact (gbo_0RB0LC_0RC1RD_0RD1LA_1LC1RD j)].
    rewrite (gso_0RB0LC_0RC1RD_0RD1LA_1LC1RD p j E).
    exact (srun_sound tm true true chb_0RB0LC_0RC1RD_0RD1LA_1LC1RD B0_0RB0LC_0RC1RD_0RD1LA_1LC1RD BB1_0RB0LC_0RC1RD_0RD1LA_1LC1RD 4 7
             run_boot_0RB0LC_0RC1RD_0RD1LA_1LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_0RB0LC_0RC1RD_0RD1LA_1LC1RD).
    split; [| exact (geo_0RB0LC_0RC1RD_0RD1LA_1LC1RD p j E)].
