      with (l := [SRotL 1; SWin 5; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1LA0LC_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1LA0LC_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LA0LC_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 5; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LA0LC_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LC_1LA0LC_0RD1LA_1LC1RD
      with (l := [SRotL 1; SWin 5]).
    vm_compute; reflexivity.
