  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LA1LC_1RD0LC_0RD1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LA1LC_1RD0LC_0RD1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LA1LC_1RD0LC_0RD1LA : forall t, ~ In t pins_0RB0LC_1LA1LC_1RD0LC_0RD1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LA1LC_1RD0LC_0RD1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 5]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 5; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LC_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 3]).
    vm_compute; reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LA1LC_1RD0LC_0RD1LA : NonHalt tm_0RB0LC_1LA1LC_1RD0LC_0RD1LA /\ QHBoundTr 32779478 tm_0RB0LC_1LA1LC_1RD0LC_0RD1LA /\ QuasiHaltsTr tm_0RB0LC_1LA1LC_1RD0LC_0RD1LA.
