  - intros p _. apply lap_0RB0LC_1LA1LC_1RD0LC_0RD1LA.
  - intros t Ht p _. apply fire_0RB0LC_1LA1LC_1RD0LC_0RD1LA. exact Ht.
  - exact wit_0RB0LC_1LA1LC_1RD0LC_0RD1LA.
  - apply qcleb_QC_01. reflexivity.
Qed.

