    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1LD_0RD1LA_1LC1RD [SWinR 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
