Theorem qhtr_0RB0LC_1LC1RB_0LD1LA_0RD1RA : NonHalt tm_0RB0LC_1LC1RB_0LD1LA_0RD1RA /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0LD1LA_0RD1RA /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0LD1LA_0RD1RA.
