(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RD1LA_1LA0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0RD1LA_1LA0RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_0RD1LA_1LA0RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1LC1RB_0RD1LA_1LA0RD : stepn tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD 9 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LC_1LC1RB_0RD1LA_1LA0RD : existsb (fun tg => cfires tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD c0 9 tg) pins_0RB0LC_1LC1RB_0RD1LA_1LA0RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_0RD1LA_1LA0RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_0RD1LA_1LA0RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RD1LA_1LA0RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_0RD1LA_1LA0RD : forall t, ~ In t pins_0RB0LC_1LC1RB_0RD1LA_1LA0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_0RB0LC_1LC1RB_0RD1LA_1LA0RD : NonHalt tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD /\ QHBoundTr 32779478 tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD /\ QuasiHaltsTr tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
Proof.
  apply (lap_qh_stage tmm_0RB0LC_1LC1RB_0RD1LA_1LA0RD pins_0RB0LC_1LC1RB_0RD1LA_1LA0RD Cc 1 9 32779478).
  - exact bootq_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RD1LA_1LA0RD. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
  - apply qcleb_QC_01. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1LA0RD : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1LA0RD /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1LA0RD /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1LA0RD.
